// Some portions generated by Codex
package org.eclipse.rdf4j.repository.manager;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Path;

import org.eclipse.rdf4j.repository.config.RepositoryConfigException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class RepositoryIdValidatorTest {

	@Test
	void rejectsUnsafeRepositoryIdentifiers() {
		for (String id : new String[] { "", " ", ".", "..", "a/b", "a\\b", "/absolute", "C:repo",
				"C:\\repo", "\\\\server\\share", "nul\0id", "line\nbreak", "a%2fb", "%2e%2e",
				"a\u2044b", "a\u29f5b", "a\u29f9b", "a\uff0fb", "a\uff3cb", "re\u0301pertoire", "NUL",
				"con.txt", "CONIN$", "conin$.txt", "CONOUT$", "conout$.log", "COM\u00b9", "\uff23\uff2f\uff2e",
				"repo.", "repo\uff0e", "repo ", "repo:name", "repo*name" }) {
			assertThatThrownBy(() -> RepositoryIdValidator.validate(id))
					.as("repository ID %s", id)
					.isInstanceOf(RepositoryConfigException.class)
					.hasMessageContaining("Repository ID");
		}
	}

	@Test
	void preservesOrdinaryRepositoryIdentifiers() {
		for (String id : new String[] { "repository", "repository-1", "repository_1", "repository name",
				"répertoire" }) {
			assertThatCode(() -> RepositoryIdValidator.validate(id)).as("repository ID %s", id)
					.doesNotThrowAnyException();
		}
	}

	@Test
	void resolvesExactlyOneChildOfRepositoryRoot(@TempDir Path temporaryDirectory) {
		Path repositories = temporaryDirectory.resolve("repositories");

		Path resolved = RepositoryIdValidator.resolveRepositoryDirectory(repositories, "valid-id");

		assertThat(resolved).isEqualTo(repositories.resolve("valid-id").toAbsolutePath().normalize());
		assertThatThrownBy(() -> RepositoryIdValidator.resolveRepositoryDirectory(repositories, "../escape"))
				.isInstanceOf(RepositoryConfigException.class);
	}
}
